WITH RECURSIVE department_tree AS (SELECT id, name, parent_id, 0 AS depth, gmt_create FROM department_info WHERE status != -1
AND id = #{deptId}
AND parent_id is null
UNION ALL SELECT d.id, d.name, d.parent_id, dt.depth +1 as depth, d.gmt_create FROM department_info d INNER JOIN department_tree dt ON d.parent_id = dt.id WHERE status != -1
AND dt.depth < #{depth}
) SELECT * FROM department_tree ORDER BY gmt_create DESC;

WITH RECURSIVE department_tree AS (SELECT id, name, parent_id, gmt_create FROM department_info WHERE id IN
#{id}
AND status != -1 UNION ALL SELECT d.id, d.name, d.parent_id,d.gmt_create FROM department_info d INNER JOIN department_tree dt ON d.parent_id = dt.id WHERE status != -1 ) SELECT distinct * FROM department_tree ORDER BY gmt_create DESC;

SELECT t1.*
FROM gienrag.department_info t1 LEFT JOIN gienrag.department_info t2 ON t1.parent_id = t2.id
WHERE t1.name = #{deptName} AND t2.name = #{parentDeptName}
